select case when suppliers.rating >= 3.5 then 'high' when suppliers.rating >= 2.2 then 'mid' else 'low' end as rating_bucket, suppliers.country, min(products.price) as min_price, count(products.cost) as cost_count from products left join suppliers on products.supplier_id = suppliers.id group by case when suppliers.rating >= 3.5 then 'high' when suppliers.rating >= 2.2 then 'mid' else 'low' end, suppliers.country order by country
